<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
require_admin();
require __DIR__ . '/anamnesis-bootstrap.php';
require __DIR__ . '/patient-layout.php';

$pdo = db(); $message = ''; $error = '';
$editId = (int)($_GET['edit'] ?? $_POST['anamnesis_question_id'] ?? 0);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string)($_POST['action'] ?? 'save_question'); $id = (int)($_POST['anamnesis_question_id'] ?? 0);
    if ($action === 'save_print_settings') {
        $headerColor = preg_match('/^#[0-9a-fA-F]{6}$/', (string)($_POST['header_color'] ?? '')) ? (string)$_POST['header_color'] : '#14843c';
        save_anamnesis_print_settings([
            'title' => mb_substr(trim((string)($_POST['print_title'] ?? 'VOX İ.M. - HASTA KARTI')), 0, 120),
            'header_color' => $headerColor,
            'font_size' => (string)max(9, min(16, (int)($_POST['font_size'] ?? 11))),
            'question_font_size' => (string)max(9, min(16, (int)($_POST['question_font_size'] ?? 11))),
            'layout' => mb_substr((string)($_POST['layout'] ?? ''), 0, 2000),
        ]);
        $message = 'Yazıcı çıktısı tasarımı kaydedildi.';
    } elseif ($action === 'delete_question') {
        $pdo->prepare('DELETE FROM anamnesis_question_definitions WHERE id=?')->execute([$id]); $message = 'Anamnez sorusu silindi.';
    } else {
        $name = trim((string)($_POST['name'] ?? '')); $active = isset($_POST['active']) ? 1 : 0; $sort = (int)($_POST['sort_order'] ?? 0);
        if ($name === '') $error = 'Soru alanı zorunludur.';
        else {
            $duplicate = $pdo->prepare('SELECT id FROM anamnesis_question_definitions WHERE name=? AND id<>?'); $duplicate->execute([$name, $id]);
            if ($duplicate->fetchColumn()) $error = 'Bu soru zaten kayıtlı.';
            elseif ($id) { $pdo->prepare('UPDATE anamnesis_question_definitions SET name=?,detail_label=?,active=?,sort_order=? WHERE id=?')->execute([$name,trim((string)($_POST['detail_label'] ?? '')),$active,$sort,$id]); $message='Anamnez sorusu güncellendi.'; }
            else { $pdo->prepare('INSERT INTO anamnesis_question_definitions(name,detail_label,active,sort_order) VALUES(?,?,?,?)')->execute([$name,trim((string)($_POST['detail_label'] ?? '')),$active,$sort]); $message='Anamnez sorusu eklendi.'; }
        }
    }
}
$edit = ['id'=>0,'name'=>'','detail_label'=>'','active'=>1,'sort_order'=>0];
if ($editId) { $statement=$pdo->prepare('SELECT * FROM anamnesis_question_definitions WHERE id=?'); $statement->execute([$editId]); $edit=$statement->fetch() ?: $edit; }
$rows = anamnesis_question_definitions();
$printSettings = anamnesis_print_settings();
patient_header('Ayarlar - Anamnez', 'settings');
?>
<main class="patient-container personnel-page"><nav class="settings-tabs"></nav>
  <?php if($message):?><p class="vox-message success"><?=e($message)?></p><?php endif?><?php if($error):?><p class="vox-message error"><?=e($error)?></p><?php endif?>
  <details class="vuexy-form-card definition-accordion"<?=($editId||$error)?' open':''?>><summary class="form-card-title"><span><h1><?=$editId?'Anamnez Sorusu Düzenle':'Yeni Anamnez Sorusu'?></h1><p>Hasta kartındaki Evet / Hayır sorularını yönetin.</p></span><i class="definition-chevron" aria-hidden="true"></i></summary>
    <form method="post" class="personnel-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_question"><input type="hidden" name="anamnesis_question_id" value="<?=(int)$edit['id']?>"><label>Soru<input name="name" maxlength="512" value="<?=e($edit['name'])?>" required></label><label>Açıklama Alanı Başlığı<input name="detail_label" maxlength="190" placeholder="Örn. Ne kadar süre" value="<?=e((string)$edit['detail_label'])?>"></label><label>Sıra<input type="number" name="sort_order" value="<?=(int)$edit['sort_order']?>"></label><label class="personnel-check"><span>Durum</span><span><input type="checkbox" name="active" <?=$edit['active']?'checked':''?>> Aktif</span></label><div class="personnel-actions"><button type="submit"><?=$editId?'Güncelle':'Kaydet'?></button><?php if($editId):?><a class="edit-definition" href="<?=url('anamnesis-questions.php')?>">İptal</a><?php endif?></div></form>
  </details>
  <section class="vuexy-form-card"><header class="form-card-title"><h2>Anamnez Soruları</h2><p><?=count($rows)?> kayıt</p></header><div class="table-responsive"><table class="personnel-table anamnesis-question-table"><thead><tr><th class="question-column">Soru</th><th class="detail-column">Açıklama Alanı</th><th class="sort-column">Sıra</th><th class="status-column">Durum</th><th class="actions-column">İşlemler</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="question-column"><?=e($row['name'])?></td><td class="detail-column"><?=e((string)$row['detail_label'])?:'—'?></td><td class="sort-column"><?=(int)$row['sort_order']?></td><td class="status-column"><span class="status-pill <?=$row['active']?'active':'passive'?>"><?=$row['active']?'Aktif':'Pasif'?></span></td><td class="actions-column"><a class="edit-definition" href="<?=url('anamnesis-questions.php?edit='.(int)$row['id'])?>">Düzenle</a><form method="post" class="inline" onsubmit="return confirm('Bu soru silinsin mi?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_question"><input type="hidden" name="anamnesis_question_id" value="<?=(int)$row['id']?>"><button type="submit" class="delete-definition">Sil</button></form></td></tr><?php endforeach?></tbody></table></div></section>
  <details class="vuexy-form-card definition-accordion"><summary class="form-card-title"><span><h2>Yazıcı Çıktısı Tasarımı</h2><p>Anamnez hasta kartının yazdırılmış görünümünü düzenleyin.</p></span><i class="definition-chevron" aria-hidden="true"></i></summary>
    <form method="post" class="personnel-form print-design-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_print_settings"><input type="hidden" name="layout" value="<?=e($printSettings['layout'])?>"><label>Başlık<input name="print_title" maxlength="120" value="<?=e($printSettings['title'])?>" required></label><label>Başlık Rengi<input type="color" name="header_color" value="<?=e($printSettings['header_color'])?>"></label><label>Gövde Yazı Boyutu<input type="number" name="font_size" min="9" max="16" value="<?=e($printSettings['font_size'])?>"></label><label>Soru Yazı Boyutu<input type="number" name="question_font_size" min="9" max="16" value="<?=e($printSettings['question_font_size'])?>"></label><div class="a4-designer" aria-label="A4 yazdırma tasarım alanı"><div class="a4-guides"></div><div class="design-block" data-design-block="header">Başlık</div><div class="design-block" data-design-block="meta">Hasta / Tarih</div><div class="design-block design-block-large" data-design-block="questions">Sorular</div><div class="design-block" data-design-block="footer">Alt Bilgi</div></div><p class="designer-help">Kutuları sürükleyin; bırakınca en yakın kılavuz çizgisine hizalanır.</p><div class="personnel-actions"><button type="submit">Tasarımı Kaydet</button><button type="button" class="print-preview-button">Ön Görüntü</button></div></form>
  </details>
</main>
