.print-design-form{align-items:flex-start}.a4-designer{position:relative;flex:0 0 420px;width:420px;height:594px;max-width:100%;border:1px solid #aeb5c3;background:#fff;box-shadow:0 2px 12px #1e283c18;overflow:hidden}.a4-guides{position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(to right,rgba(25,169,75,.22) 1px,transparent 1px),linear-gradient(to bottom,rgba(25,169,75,.22) 1px,transparent 1px);background-size:21px 21px}.a4-designer::before{content:'A4 · 210 × 297 mm';position:absolute;right:10px;bottom:8px;color:#8b8a95;font-size:11px}.design-block{position:absolute;z-index:1;display:flex;align-items:center;justify-content:center;min-width:82px;padding:7px 10px;border:1px dashed #14843c;border-radius:4px;background:#ecf8f0;color:#126c32;font-size:12px;font-weight:700;cursor:grab;user-select:none}.design-block:active{cursor:grabbing}.design-block-large{width:270px;height:270px}.designer-help{flex-basis:100%;margin:0;color:#6e6c7b;font-size:13px}.print-preview-button{background:#30435d!important}.print-preview-modal[hidden]{display:none!important}.print-preview-modal{position:fixed;inset:0;z-index:3000;display:grid;place-items:center;padding:20px;background:rgba(25,28,38,.58)}.print-preview-sheet{position:relative;width:min(620px,100%);aspect-ratio:210/297;background:#fff;box-shadow:0 18px 46px rgba(0,0,0,.3);overflow:hidden}.print-preview-sheet button{position:absolute;right:12px;top:8px;border:0;background:transparent;font-size:25px;cursor:pointer}.print-preview-block{position:absolute;border:1px dashed #cbd3ce;padding:6px 8px;color:#23343a;font-size:12px}.print-preview-block.header{font-weight:700}.print-preview-block.questions{width:62%;height:47%;line-height:1.8}@media(max-width:760px){.a4-designer{flex-basis:100%;width:100%;height:calc((100vw - 48px) * 1.414)}}
